package com.designcollab.canvas.websocket;

import com.designcollab.canvas.dto.DeleteElementRequest;
import com.designcollab.canvas.service.CanvasPersistenceService;
import com.designcollab.canvas.service.WorkspacePermissionService;
import org.springframework.messaging.handler.annotation.DestinationVariable;
import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Controller;
import java.security.Principal;

@Controller
public class CanvasCollabHandler {

    private final CanvasPersistenceService persistenceService;
    private final SimpMessagingTemplate messagingTemplate;
    private final WorkspacePermissionService permissionService;

    public CanvasCollabHandler(CanvasPersistenceService persistenceService, SimpMessagingTemplate messagingTemplate, WorkspacePermissionService permissionService) {
        this.persistenceService = persistenceService;
        this.messagingTemplate = messagingTemplate;
        this.permissionService = permissionService;
    }

    @MessageMapping("/workspace/{workspaceId}/canvas/element-delete")
    public void deleteCanvasElement(
            @DestinationVariable Long workspaceId,
            @Payload DeleteElementRequest request,
            Principal principal) {
        if (!permissionService.canEditWorkspace(principal.getName(), workspaceId)) {
            throw new AccessDeniedException("User does not have edit permissions on workspace " + workspaceId);
        }
        persistenceService.removeElement(workspaceId, request.getElementId());
        messagingTemplate.convertAndSend("/topic/workspace/" + workspaceId + "/canvas", request);
    }
}
